onClick:
{{
  Insert_Machine.run()
    .then((res) => {
      // 1. On mémorise l'ID de la nouvelle machine
      storeValue('nouvelle_machine_id', res[0].ID_Machine);

      // 2. On rafraîchit la liste des machines du client
      return Get_Machines_Client.run();
    })
    .then(() => {
      // 3. On ferme la modale de la machine
      closeModal('modal_add_machine');
    })
    .then(() => {
      // 4. On réouvre la modale d'intervention
      return showModal('modal_add_intervention');
    })
    .then(() => {
      showAlert('Machine ajoutée au parc avec succès !', 'success');
    })
    .catch(() => {
      showAlert("Erreur lors de l'enregistrement de la machine.", 'error');
    });
}}
